using Astronomy.MediaFactory.Core.DocumentaryBlueprint;
namespace Astronomy.MediaFactory.Tests.DocumentaryBlueprint;
public sealed class DocumentaryNarrativeRevisionConvergenceAdvanceRequestTests
{
    [Fact] public void Rejects_invalid_boundaries() { var s=OrionDocumentaryNarrativeRevisionConvergenceFixture.InitiallyInvalidState(); var c=OrionDocumentaryNarrativeRevisionConvergenceFixture.SuccessfulCycle(); var t=DateTimeOffset.Parse("2026-01-01Z"); Assert.Throws<ArgumentNullException>(()=>new DocumentaryNarrativeRevisionConvergenceAdvanceRequest(null!,c,t,"x","1.0","c")); Assert.Throws<ArgumentNullException>(()=>new DocumentaryNarrativeRevisionConvergenceAdvanceRequest(s,null!,t,"x","1.0","c")); Assert.Throws<ArgumentException>(()=>new DocumentaryNarrativeRevisionConvergenceAdvanceRequest(s,c,default,"x","1.0","c")); Assert.Throws<ArgumentException>(()=>new DocumentaryNarrativeRevisionConvergenceAdvanceRequest(s,c,t," ","1.0","c")); Assert.Throws<ArgumentException>(()=>new DocumentaryNarrativeRevisionConvergenceAdvanceRequest(s,c,t,"x","2.0","c")); Assert.Throws<ArgumentException>(()=>new DocumentaryNarrativeRevisionConvergenceAdvanceRequest(s,c,t,"x","1.0"," ")); }
    [Fact] public void Preserves_exact_objects_values_and_round_trips() { var s=OrionDocumentaryNarrativeRevisionConvergenceFixture.InitiallyInvalidState(); var c=OrionDocumentaryNarrativeRevisionConvergenceFixture.SuccessfulCycle(); var r=OrionDocumentaryNarrativeRevisionConvergenceFixture.Request(s,c); Assert.Same(s,r.CurrentState); Assert.Same(c,r.CompletedCycleResult); Assert.Equal(" convergence advancer ",r.AdvancedBy); Assert.Equal(TimeSpan.FromHours(-4),r.AdvancedUtc.Offset); DocumentaryNarrativeRevisionConvergencePolicyTests.RoundTrip(r); }
}
